# ========================================================================# Script de Setup do Backend para Desenvolvedores Frontend (Windows)# ========================================================================param(    [string]$RepoOwner = "CHANGEME_SEU_USUARIO_GITHUB")$ErrorActionPreference = "Stop"$DefaultTag = "latest"Write-Host "🚀 Sistema de Gestão de Patrimônio - Setup Backend para Frontend" -ForegroundColor CyanWrite-Host "=================================================================" -ForegroundColor CyanWrite-Host ""# Verificar Dockerif (-not (Get-Command docker -ErrorAction SilentlyContinue)) {    Write-Host "❌ Docker não está instalado. Instale o Docker Desktop primeiro." -ForegroundColor Red    Write-Host "   Acesse: https://docs.docker.com/desktop/install/windows-install/" -ForegroundColor Yellow    exit 1}# Solicitar REPO_OWNER se não fornecidoif ($RepoOwner -eq "CHANGEME_SEU_USUARIO_GITHUB") {    $RepoOwner = Read-Host "📝 Informe o usuário/organização do GitHub Container Registry"    if ([string]::IsNullOrWhiteSpace($RepoOwner)) {        Write-Host "❌ REPO_OWNER é obrigatório. Saindo." -ForegroundColor Red        exit 1    }}Write-Host ""Write-Host "📦 Imagens que serão baixadas:" -ForegroundColor YellowWrite-Host "   - ghcr.io/$RepoOwner/users-service:$DefaultTag"Write-Host "   - ghcr.io/$RepoOwner/auth-service:$DefaultTag"Write-Host "   - ghcr.io/$RepoOwner/patrimonio-service:$DefaultTag"Write-Host "   - ghcr.io/$RepoOwner/categorias-service:$DefaultTag"Write-Host "   - ghcr.io/$RepoOwner/audit-service:$DefaultTag"Write-Host "   - ghcr.io/$RepoOwner/events-service:$DefaultTag"Write-Host "   - ghcr.io/$RepoOwner/api-gateway:$DefaultTag"Write-Host ""# Criar .env.prod se não existirif (-not (Test-Path ".env.prod")) {    Write-Host "📄 Criando arquivo .env.prod com configurações padrão..." -ForegroundColor Yellow        # Gerar string aleatória para segredos    $randomSecret = -join ((48..57) + (65..90) + (97..122) | Get-Random -Count 32 | ForEach-Object {[char]$_})    $randomHex = -join ((48..57) + (97..102) | Get-Random -Count 16 | ForEach-Object {[char]$_})        $envContent = @"# ========================================================================# Configuração de Desenvolvimento - Gerada Automaticamente# ========================================================================NODE_ENV=productionREPO_OWNER=$RepoOwner# Banco de DadosPOSTGRES_USER=postgresPOSTGRES_PASSWORD=postgres123POSTGRES_DB=patrimonio_inventarioDB_HOST=dbDB_PORT=5432DB_USER=postgresDB_PASS=postgres123DB_NAME=patrimonio_inventarioDB_SSL=falseDB_LOGGING=false# JWT (valores padrão para desenvolvimento - NÃO usar em produção!)JWT_ACCESS_SECRET=dev-secret-key-$randomHexJWT_REFRESH_SECRET=dev-refresh-secret-$randomHexJWT_ACCESS_EXPIRES_IN=900JWT_REFRESH_EXPIRES_IN=604800# Hash de SenhasHASH_PEPPER=dev-pepper-$randomHexHASH_SALT_ROUNDS=12# Service TokenSERVICE_TOKEN=dev-service-token-$randomHex# Tags das ImagensUSERS_IMAGE_TAG=$DefaultTagAUTH_IMAGE_TAG=$DefaultTagPATRIMONIO_IMAGE_TAG=$DefaultTagCATEGORIAS_IMAGE_TAG=$DefaultTagAUDIT_IMAGE_TAG=$DefaultTagEVENTS_IMAGE_TAG=$DefaultTagGATEWAY_IMAGE_TAG=$DefaultTag# URLs dos ServiçosAUTH_API_URL=http://auth-service:3001USERS_API_URL=http://users-service:3002PATRIMONIO_API_URL=http://patrimonio-service:3003CATEGORIAS_API_URL=http://categorias-service:3004AUDIT_API_URL=http://audit-service:3005EVENTS_API_URL=http://events-service:3006"@        $envContent | Out-File -FilePath ".env.prod" -Encoding utf8 -NoNewline    Write-Host "✅ Arquivo .env.prod criado!" -ForegroundColor Green    Write-Host ""}# Definir variáveis de ambiente$env:REPO_OWNER = $RepoOwner$env:USERS_IMAGE_TAG = $DefaultTag$env:AUTH_IMAGE_TAG = $DefaultTag$env:PATRIMONIO_IMAGE_TAG = $DefaultTag$env:CATEGORIAS_IMAGE_TAG = $DefaultTag$env:AUDIT_IMAGE_TAG = $DefaultTag$env:EVENTS_IMAGE_TAG = $DefaultTag$env:GATEWAY_IMAGE_TAG = $DefaultTagWrite-Host "📥 Baixando imagens Docker do GitHub Container Registry..." -ForegroundColor YellowWrite-Host "   (Isso pode levar alguns minutos na primeira vez)"Write-Host ""# Baixar todas as imagensdocker pull "ghcr.io/$RepoOwner/users-service:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar users-service" -ForegroundColor Yellow }docker pull "ghcr.io/$RepoOwner/auth-service:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar auth-service" -ForegroundColor Yellow }docker pull "ghcr.io/$RepoOwner/patrimonio-service:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar patrimonio-service" -ForegroundColor Yellow }docker pull "ghcr.io/$RepoOwner/categorias-service:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar categorias-service" -ForegroundColor Yellow }docker pull "ghcr.io/$RepoOwner/audit-service:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar audit-service" -ForegroundColor Yellow }docker pull "ghcr.io/$RepoOwner/events-service:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar events-service" -ForegroundColor Yellow }docker pull "ghcr.io/$RepoOwner/api-gateway:$DefaultTag"if ($LASTEXITCODE -ne 0) { Write-Host "⚠️  Falha ao baixar api-gateway" -ForegroundColor Yellow }Write-Host ""Write-Host "🐳 Subindo containers Docker Compose..." -ForegroundColor YellowWrite-Host ""docker compose -f docker-compose.deploy.yml up -dif ($LASTEXITCODE -ne 0) {    Write-Host "❌ Erro ao subir containers. Verifique os logs." -ForegroundColor Red    exit 1}Write-Host ""Write-Host "⏳ Aguardando serviços inicializarem (aguarde ~30 segundos)..." -ForegroundColor YellowStart-Sleep -Seconds 20Write-Host ""Write-Host "🏥 Verificando saúde dos serviços..." -ForegroundColor YellowWrite-Host ""function Test-HealthEndpoint {    param($Url, $Name)    $maxAttempts = 10    $attempt = 1        while ($attempt -le $maxAttempts) {        try {            $response = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 2 -ErrorAction Stop            Write-Host "✅ $Name está funcionando" -ForegroundColor Green            return $true        } catch {            if ($attempt -lt $maxAttempts) {                Start-Sleep -Seconds 2            }            $attempt++        }    }        Write-Host "⚠️  $Name ainda não está respondendo (tente novamente em alguns segundos)" -ForegroundColor Yellow    return $false}Test-HealthEndpoint "http://localhost:3001/health" "Auth Service"Test-HealthEndpoint "http://localhost:3002/health" "Users Service"Test-HealthEndpoint "http://localhost:3003/health" "Patrimonio Service"Test-HealthEndpoint "http://localhost:3004/health" "Categorias Service"Test-HealthEndpoint "http://localhost:3005/health" "Audit Service"Test-HealthEndpoint "http://localhost:3006/health" "Events Service"Test-HealthEndpoint "http://localhost:3100/health" "API Gateway"Write-Host ""Write-Host "=================================================================" -ForegroundColor CyanWrite-Host "✅ Setup concluído!" -ForegroundColor GreenWrite-Host ""Write-Host "📋 Informações importantes:" -ForegroundColor CyanWrite-Host "   - API Gateway: http://localhost:3100"Write-Host "   - Auth Service: http://localhost:3001"Write-Host "   - Users Service: http://localhost:3002"Write-Host "   - Patrimonio Service: http://localhost:3003"Write-Host ""Write-Host "📝 Comandos úteis:" -ForegroundColor CyanWrite-Host "   - Ver logs:        docker compose -f docker-compose.deploy.yml logs -f"Write-Host "   - Parar tudo:      docker compose -f docker-compose.deploy.yml down"Write-Host "   - Reiniciar:       docker compose -f docker-compose.deploy.yml restart"Write-Host "   - Ver status:      docker compose -f docker-compose.deploy.yml ps"Write-Host ""Write-Host "⚠️  NOTA: Esta configuração usa valores padrão de desenvolvimento." -ForegroundColor YellowWrite-Host "   Para producao, edite o arquivo .env.prod e substitua os segredos!" -ForegroundColor YellowWrite-Host ""